  ('9b26a248-0609-52d3-b7a3-acdd6eb5b1ba', null, (select id from public.skills where slug = 'write-g12-paragraph-transitions'), null, 'medium',
   $q$Read: "(1) Once the glaze has dried, the pieces return to the kiln for a second, hotter firing. (2) A potter first shapes the clay on a wheel and lets it dry until it is firm but not brittle. (3) After this first firing, the hardened pieces are dipped in glaze. (4) The dried pieces are then fired at a moderate temperature to drive out any remaining moisture." Which order of the sentences creates the most logical paragraph?$q$, $q$[{"text":"2, 4, 1, 3","is_correct":false,"misconception_token":"misplaces-last-step"},{"text":"2, 4, 3, 1","is_correct":true},{"text":"4, 2, 3, 1","is_correct":false,"misconception_token":"misplaces-first-step"},{"text":"2, 3, 4, 1","is_correct":false,"misconception_token":"ignores-sequence-signal"}]$q$::jsonb, $q$2, 4, 3, 1$q$, $q$Sentence 2 says "first," sentence 4 refers to "the dried pieces," sentence 3 follows "this first firing," and sentence 1 describes the "second" firing, so the order is 2, 4, 3, 1. The order 2, 3, 4, 1 fails because sentence 3 mentions a first firing that has not happened yet.$q$, 'draft', null)
