  ('5652230f-ff31-5358-a8b2-899583ab3d3d', null, (select id from public.skills where slug = 'write-g12-precise-language'), null, 'medium',
   $q$Read the sentences: "The bridge opened in 1932. It was made of steel. It spanned the river gorge." Which revision combines them most effectively?$q$, $q$[{"text":"The bridge, which spanned the river gorge, opened in 1932.","is_correct":false,"misconception_token":"drops-detail"},{"text":"The steel bridge, which spanned the river gorge, opened in 1932.","is_correct":true},{"text":"The bridge opened in 1932, it was made of steel, it spanned the river gorge.","is_correct":false,"misconception_token":"comma-splice"},{"text":"The bridge opened in 1932 and it was made of steel and it spanned the river gorge.","is_correct":false,"misconception_token":"stringy-coordination"}]$q$::jsonb, $q$The steel bridge, which spanned the river gorge, opened in 1932.$q$, $q$Turning "made of steel" into the adjective "steel" and the gorge detail into a clause keeps all three facts in one smooth sentence. The last choice is smooth too, but it drops the fact that the bridge was steel.$q$, 'draft', null)
