  ('d8f8cabe-758c-50ad-bd90-392e4dff25b8', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'medium',
   $q$Which sentence correctly marks the boundary between its clauses?$q$, $q$[{"text":"The library installed solar panels last spring; its electricity bill, therefore, dropped by nearly a third.","is_correct":true},{"text":"The library installed solar panels last spring, its electricity bill, therefore, dropped by nearly a third.","is_correct":false,"misconception_token":"comma-splice-unfixed"},{"text":"The library installed solar panels last spring, therefore its electricity bill dropped by nearly a third.","is_correct":false,"misconception_token":"conjunctive-adverb-with-comma-only"},{"text":"The library installed solar panels last spring its electricity bill therefore dropped by nearly a third.","is_correct":false,"misconception_token":"fused-sentence"}]$q$::jsonb, $q$The library installed solar panels last spring; its electricity bill, therefore, dropped by nearly a third.$q$, $q$The semicolon separates the two independent clauses, and "therefore" is set off as an interrupter within the second clause. Putting "therefore" inside commas does not fix the comma after "spring," which still joins two independent clauses.$q$, 'draft', null)
