  ('d3c40494-8eca-5e3b-9ec5-c6cbffbfeb2b', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'medium',
   $q$Read the sentences: "The translation app handles common phrases well. Struggles, however, with idioms that do not translate word for word." Which revision fixes the fragment?$q$, $q$[{"text":"The translation app handles common phrases well, however, it struggles with idioms that do not translate word for word.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The translation app handles common phrases well. However, struggles with idioms that do not translate word for word.","is_correct":false,"misconception_token":"fragment-unfixed"},{"text":"The translation app handles common phrases well; but struggles with idioms that do not translate word for word.","is_correct":false,"misconception_token":"semicolon-before-phrase"},{"text":"The translation app handles common phrases well but struggles with idioms that do not translate word for word.","is_correct":true}]$q$::jsonb, $q$The translation app handles common phrases well but struggles with idioms that do not translate word for word.$q$, $q$Joining the two verbs with "but" creates a compound predicate that shares the subject "app." Adding "it" after "however" supplies a subject but joins two independent clauses with only commas, creating a comma splice.$q$, 'draft', null)
