  ('fd3f7dad-8ee2-58f3-8cfd-7578ed6a3f1d', null, (select id from public.skills where slug = 'write-g12-sentence-structure'), null, 'hard',
   $q$Read the sentence: "The ancient caravan routes carried silk and spices westward ___ they also carried ideas, including new methods of papermaking and astronomy." Which choice correctly completes the sentence?$q$, $q$[{"text":"westward; just as important,","is_correct":true},{"text":"westward just as important,","is_correct":false,"misconception_token":"fused-sentence"},{"text":"westward, just as important;","is_correct":false,"misconception_token":"misplaced-semicolon"},{"text":"westward, just as important,","is_correct":false,"misconception_token":"comma-splice-created"}]$q$::jsonb, $q$westward; just as important,$q$, $q$"Just as important" is a transitional phrase that belongs to the second clause, so the semicolon must come before it to mark the boundary between the independent clauses. Placing the semicolon after the phrase attaches the transition to the wrong clause and leaves a comma splice after "westward."$q$, 'draft', null)
