  ('75f6ccf0-0da1-5cb1-9883-76441e8a13df', null, (select id from public.skills where slug = 'modifier-placement'), null, 'easy',
   $q$Which sentence contains a misplaced modifier?$q$, $q$[{"text":"From a neighbor, Lucia bought a bike that needed a chain.","is_correct":false,"misconception_token":"flags-opening-phrase"},{"text":"Lucia bought a bike from a neighbor with a flat tire.","is_correct":true},{"text":"Lucia bought a bike with a flat tire from a neighbor.","is_correct":false,"misconception_token":"flags-correct-phrase-order"},{"text":"Lucia rode her new bike to the park after school.","is_correct":false,"misconception_token":"flags-ordinary-sentence"}]$q$::jsonb, $q$Lucia bought a bike from a neighbor with a flat tire.$q$, $q$In "a neighbor with a flat tire," the phrase sits next to "neighbor," so it sounds like the neighbor has the flat tire. Moving the phrase next to "bike," as in the first sentence, fixes the problem.$q$, 'draft', null)
