  ('53c31ded-f34c-5989-8333-6d2acd8f5e87', null, (select id from public.skills where slug = 'modifier-placement'), null, 'easy',
   $q$Kenji packed one thing for the trip, a sweater, and nothing else. Which sentence says this clearly?$q$, $q$[{"text":"Only Kenji packed a sweater for the trip.","is_correct":false,"misconception_token":"only-modifies-subject"},{"text":"Kenji packed only a sweater for the trip.","is_correct":true},{"text":"Kenji packed a sweater for the trip only.","is_correct":false,"misconception_token":"only-modifies-purpose"},{"text":"Kenji packed a sweater for the only trip.","is_correct":false,"misconception_token":"only-modifies-wrong-noun"}]$q$::jsonb, $q$Kenji packed only a sweater for the trip.$q$, $q$"Only" limits the word right after it, so "only a sweater" says the sweater was the one thing he packed. "Only Kenji" means no one else packed a sweater, which is a different idea.$q$, 'draft', null)
